-- News management: the public News page reads its notices from this table instead of
-- src/content/news.ts, and the admin adds, edits, hides and deletes them. The 49 notices from that
-- file are copied in; created_at is staggered so notices sharing a date keep their order.
CREATE TABLE "news_entries" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"published_on" date NOT NULL,
	"text_de" text NOT NULL,
	"text_en" text,
	"visible" boolean DEFAULT true NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "news_entries_text_de_length" CHECK (char_length("news_entries"."text_de") between 1 and 500),
	CONSTRAINT "news_entries_text_en_length" CHECK ("news_entries"."text_en" IS NULL OR char_length("news_entries"."text_en") between 1 and 500)
);
--> statement-breakpoint
CREATE INDEX "news_entries_published_idx" ON "news_entries" USING btree ("published_on" DESC NULLS LAST,"created_at" DESC NULLS LAST);
