INSERT INTO "news_entries" ("published_on", "text_de", "text_en", "created_at") VALUES
  ('2026-11-03', 'Zwei unserer Trader sind unerwartet ausgeschieden.', 'Two of our traders have unexpectedly left the company.', now() - interval '0 seconds'),
  ('2026-10-20', 'Vom 22.10. bis 27.10. treffen wir uns mit Tradern, der Support antwortet ggf. verzögert.', 'From 22.10. to 27.10. we will be meeting with traders; support may respond with a delay.', now() - interval '1 seconds'),
  ('2026-10-10', 'Neue EU-SEPA-Bankverbindung ist da, Einzahlungen von 200 bis 700 €.', 'A new EU SEPA bank account is available, for deposits of €200 to €700.', now() - interval '2 seconds'),
  ('2026-10-09', 'Einzahlungen per Monero (XMR, anonymer Coin) sind ab sofort möglich, Auszahlungen ab 01.27.', 'Deposits via Monero (XMR, anonymous coin) are now possible; withdrawals from January 2027.', now() - interval '3 seconds'),
  ('2026-10-02', 'Die Zusammenarbeit mit einem Trader wurde beendet.', 'Our collaboration with one trader has ended.', now() - interval '4 seconds'),
  ('2026-08-21', 'Neue EU-SEPA-Bankverbindung ist da, Einzahlungen von 100 bis 900 €.', 'A new EU SEPA bank account is available, for deposits of €100 to €900.', now() - interval '5 seconds'),
  ('2026-07-08', 'Wegen eines Live-Business-Meetings vom 09.07. bis 12.07. ist der Support nur per E-Mail erreichbar.', 'Due to a live business meeting from 09.07. to 12.07., support is only available via email.', now() - interval '6 seconds'),
  ('2026-06-30', 'Wegen Büroumzug werden Kontostände bis zum 03.07. aktualisiert.', 'Due to an office move, account balances will be updated until 03.07.', now() - interval '7 seconds'),
  ('2026-06-02', 'Voraussichtlich ab dem 05.06. stehen die Renditen für den Mai fest und sind sichtbar.', 'The returns for May are expected to be final and visible from 05.06.', now() - interval '8 seconds'),
  ('2026-05-03', 'Die Kontostände werden nach dem 05.05. aktualisiert.', 'Account balances will be updated after 05.05.', now() - interval '9 seconds'),
  ('2026-04-05', 'Die ersten Konten werden ab dem 06.04. berechnet.', 'The first accounts will be calculated from 06.04.', now() - interval '10 seconds'),
  ('2026-04-01', 'Der Pool ist für neue Investoren geschlossen.', 'The pool is closed to new investors.', now() - interval '11 seconds'),
  ('2026-03-30', 'Der Pool wurde für Neukunden geschlossen, Anfragen bis zum 30.03.26 werden noch beantwortet.', 'The pool has been closed to new customers; enquiries received by 30.03.26 will still be answered.', now() - interval '12 seconds'),
  ('2026-03-20', 'Ab sofort akzeptieren wir für Ein- und Auszahlungen Monero (XMR, anonymer Coin) bis 3.000 Euro.', 'We now accept Monero (XMR, anonymous coin) for deposits and withdrawals up to €3,000.', now() - interval '13 seconds'),
  ('2026-03-01', 'Die Renditen der Trader für Februar erscheinen voraussichtlich ab dem 04.03.26 online.', 'The traders'' returns for February are expected to be online from 04.03.26.', now() - interval '14 seconds'),
  ('2026-02-18', 'Das Limit für Einzahlungen ändert sich ab dem 10.03.26 zu mindestens 750 Euro bis maximal 75.000 Euro.', 'From 10.03.26 the deposit limit changes to a minimum of €750 and a maximum of €75,000.', now() - interval '15 seconds'),
  ('2025-11-03', 'Aufgrund des Tsunamis gibt es Verzögerungen wegen der folgenden Strom- und Internetausfälle.', 'Due to the tsunami, there are delays because of the resulting power and internet outages.', now() - interval '16 seconds'),
  ('2025-10-18', 'Ab 20.10. können unsere Kunden eine eigene EU-IBAN bekommen, mit angeschlossener dezentraler Exchange und VISA-Karte. Damit sind auch Ein- und Auszahlungen gebührenfrei.', 'From 20.10. our customers can get their own EU IBAN, with an associated decentralized exchange and VISA card; deposits and withdrawals are then free of charge.', now() - interval '17 seconds'),
  ('2025-10-09', 'Aufgrund des Erdbebens mit Stromausfällen erfolgt die Abrechnung zum Teil 1–4 Tage später.', 'Due to the earthquake and resulting power outages, some billing will be delayed by 1–4 days.', now() - interval '18 seconds'),
  ('2025-09-28', 'Eigenes Team für den Versand der Kontoauszüge, der Versand erfolgt über Tuta-Mail (siehe „Kontakt“).', 'A dedicated team now sends the account statements, via Tuta mail (see “Contact”).', now() - interval '19 seconds'),
  ('2025-07-24', 'Die ersten 50 Investoren können nach dem 02.08.25 ihren Kontostand online einsehen.', 'The first 50 investors can view their account balance online after 02.08.25.', now() - interval '20 seconds'),
  ('2025-07-23', 'Eine Einzahlung per deutscher Kreditkarte (Visa / Mastercard, auch Debit) ist ab sofort auf Anfrage möglich.', 'Deposits by German credit card (Visa / Mastercard, also debit) are possible now, on request.', now() - interval '21 seconds'),
  ('2025-07-02', 'Voraussichtlich ab 20.07.25 ist eine Einzahlung auch per Kreditkarte (auch Debitkarte) möglich.', 'From about 20.07.25, deposits will also be possible by credit card (including debit card).', now() - interval '22 seconds'),
  ('2025-06-07', 'Geplante Zusammenarbeit mit einem Zahlungsdienstleister, Zahlart wählbar (SWIFT, BTC, Kreditkarte usw.).', 'Planned cooperation with a payment service provider, with a selectable payment method (SWIFT, BTC, credit card etc.).', now() - interval '23 seconds'),
  ('2025-05-01', 'Das Einzahlungslimit wurde von 50.000 Euro auf 60.000 Euro angepasst (der Kontostand darf höher sein).', 'The deposit limit has been raised from €50,000 to €60,000 (the account balance may be higher).', now() - interval '24 seconds'),
  ('2025-04-10', 'Bei Ein- und Auszahlungen von Börsen werden ab 16.04.25 3 % Gebühr berechnet (private Wallets 0 Euro).', 'From 16.04.25 a 3% fee applies to deposits and withdrawals from exchanges (private wallets €0).', now() - interval '25 seconds'),
  ('2025-04-10', 'Ab 15.04.25 akzeptieren wir keine Ein- und Auszahlungen von Börsen mehr, nur noch von privaten Wallets.', 'From 15.04.25 we no longer accept deposits and withdrawals from exchanges, only from private wallets.', now() - interval '26 seconds'),
  ('2025-03-28', 'Aufstockungen können ab sofort zwischen 100 und 300 Euro auch in XRP (Ripple) erfolgen.', 'Top-ups between €100 and €300 can now also be made in XRP (Ripple).', now() - interval '27 seconds'),
  ('2025-03-03', 'Nach dem Betatest wird ab Ende April für einige Kunden eine Guthabenabfrage online verfügbar sein.', 'After beta testing, an online balance check will be available for some customers from the end of April.', now() - interval '28 seconds'),
  ('2025-03-01', 'Unsere neue IBAN-Bank hat den Start im Mai 2025 nach langer Vorlaufzeit jetzt offiziell bestätigt.', 'Our new IBAN bank has now officially confirmed its launch in May 2025 after a long lead time.', now() - interval '29 seconds'),
  ('2025-02-01', 'Ab dem 02.02.25 können Einzahlungen bis 500 Euro auch per TRX (Tron) und SOL (Solana) erfolgen.', 'From 02.02.25, deposits up to €500 can also be made via TRX (Tron) and SOL (Solana).', now() - interval '30 seconds'),
  ('2025-02-01', 'Ab sofort können Einzahlungen auch in USDC (BEP20) bis 10.000 USDC erfolgen.', 'Deposits can now also be made in USDC (BEP20), up to 10,000 USDC.', now() - interval '31 seconds'),
  ('2025-01-30', 'Der Start der neuen Bank mit weiterer IBAN verzögert sich auf voraussichtlich 31.03.25.', 'The launch of the new bank with an additional IBAN is delayed until about 31.03.25.', now() - interval '32 seconds'),
  ('2024-11-24', 'Unsere neue Bank mit SEPA-Anbindung wird definitiv im April 2025 aktiv und kann dann genutzt werden.', 'Our new bank with SEPA connection will definitely be active in April 2025 and can then be used.', now() - interval '33 seconds'),
  ('2024-11-23', 'Ab dem 01.01.2025 ändert sich die Mindesteinzahlung im Pool für Neukunden auf 500 Euro.', 'From 01.01.2025 the minimum deposit in the pool for new customers changes to €500.', now() - interval '34 seconds'),
  ('2024-10-14', 'Ab dem 30.12.24 steht auch eine Adresse für USDC zur Verfügung, USDC-Auszahlungen ab 05.01.25.', 'From 30.12.24 an address for USDC will also be available; USDC withdrawals from 05.01.25.', now() - interval '35 seconds'),
  ('2024-07-27', 'Ab sofort kann auch per Tron (TRX) und BNB (Binance Coin) eingezahlt oder aufgestockt werden.', 'Deposits and top-ups can now also be made via Tron (TRX) and BNB (Binance Coin).', now() - interval '36 seconds'),
  ('2024-07-16', 'Unsere neue Bank mit IBAN ohne Ein- oder Auszahlungslimit wird voraussichtlich zum 25.12.24 aktiv sein.', 'Our new bank with an IBAN and no deposit or withdrawal limits is expected to be active from 25.12.24.', now() - interval '37 seconds'),
  ('2024-07-01', 'Investoren aus Asien können jetzt auch per Maya und GCash einzahlen oder Auszahlungen erhalten.', 'Investors in Asia can now also deposit or receive withdrawals via Maya and GCash.', now() - interval '38 seconds'),
  ('2024-07-01', 'Das Limit für Einzahlungen wurde von 30.000 Euro auf 50.000 Euro je Konto angehoben.', 'The deposit limit was raised from €30,000 to €50,000 per account.', now() - interval '39 seconds'),
  ('2024-07-01', 'Eine weitere SWIFT-Bankverbindung wurde freigeschaltet und steht ab sofort zur Verfügung.', 'Another SWIFT bank account has been activated and is available now.', now() - interval '40 seconds'),
  ('2024-06-16', 'Neue und Bestandskunden können ab sofort auch mit USDT BEP20 und TRC20 (Stablecoin) einzahlen.', 'New and existing customers can now also deposit with USDT BEP20 and TRC20 (stablecoin).', now() - interval '41 seconds'),
  ('2024-06-15', 'Voraussichtlich ab dem 28.06.24 steht eine weitere SWIFT-Bankverbindung zur Verfügung.', 'Another SWIFT bank account is expected to be available from 28.06.24.', now() - interval '42 seconds'),
  ('2024-06-14', 'Unsere Bestandskunden können ab sofort auch mit Western Union einzahlen, Details auf Anfrage.', 'Our existing customers can now also deposit via Western Union; details on request.', now() - interval '43 seconds'),
  ('2024-06-03', 'Unsere Bestandskunden können ab sofort auch mit RIA Money Transfer einzahlen, Details auf Anfrage.', 'Our existing customers can now also deposit via RIA Money Transfer; details on request.', now() - interval '44 seconds'),
  ('2024-02-17', 'Unsere neue IBAN ist voraussichtlich ab dem 30.09.2024 für Neu- und Bestandskunden aktiv.', 'Our new IBAN is expected to be active from 30.09.2024 for new and existing customers.', now() - interval '45 seconds'),
  ('2024-02-02', 'Unsere Bestandskunden können ab sofort auch mit Remitly per SEPA einzahlen, Details auf Anfrage.', 'Our existing customers can now also pay by SEPA using Remitly; details on request.', now() - interval '46 seconds'),
  ('2024-01-30', 'Für bestehende Kunden steht jetzt auch ein SWIFT-Konto zur Aufstockung per Überweisung bereit.', 'A SWIFT account is now available for existing customers to top up their balance by bank transfer.', now() - interval '47 seconds'),
  ('2024-01-10', 'Unsere Bank führt ein Empfangslimit ein, Bitcoin- und Litecoin-Zahlungen gehen weiterhin bis 30.000 Euro.', 'Our bank is introducing a receiving limit; Bitcoin and Litecoin payments are still accepted up to €30,000.', now() - interval '48 seconds');
